import java.util.*;

public class Solution {
    public int minStickers(String[] stickers, String target) {
        int n = stickers.length;
        int[][] stickerCounts = new int[n][26];
        for (int i = 0; i < n; i++) {
            for (char c : stickers[i].toCharArray()) {
                if (c >= 'a' && c <= 'z')
                    stickerCounts[i][c - 'a']++;
            }
        }
        Map<String, Integer> memo = new HashMap<>();
        memo.put("", 0);
        int ans = dp(target, stickerCounts, memo);
        return ans;
    }

    private int dp(String target, int[][] stickerCounts, Map<String,Integer> memo) {
        if (memo.containsKey(target)) return memo.get(target);
        int[] tarCounts = new int[26];
        for (char c : target.toCharArray()) tarCounts[c - 'a']++;
        int n = stickerCounts.length;
        int firstCharIdx = target.charAt(0) - 'a';
        int res = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            // optimization: skip sticker that doesn't contain the first char of target
            if (stickerCounts[i][firstCharIdx] == 0) continue;
            // apply sticker i
            StringBuilder sb = new StringBuilder();
            for (int c = 0; c < 26; c++) {
                int remain = Math.max(0, tarCounts[c] - stickerCounts[i][c]);
                for (int k = 0; k < remain; k++) sb.append((char)('a' + c));
            }
            String s = sb.toString();
            if (s.length() == target.length()) continue; // no progress
            int tmp = dp(s, stickerCounts, memo);
            if (tmp != -1) {
                res = Math.min(res, 1 + tmp);
            }
        }
        int ans = (res == Integer.MAX_VALUE) ? -1 : res;
        memo.put(target, ans);
        return ans;
    }

    // For local testing
    public static void main(String[] args) {
        Solution sol = new Solution();
        String[] stickers1 = {"with", "example", "science"};
        String target1 = "thehat";
        System.out.println(sol.minStickers(stickers1, target1)); // expected 3

        String[] stickers2 = {"notice", "possible"};
        String target2 = "basicbasic";
        System.out.println(sol.minStickers(stickers2, target2)); // expected -1
    }
}

